WITH scenarios(days, procurement_pool, logistics_pool, procurement_per_order, logistics_per_order) AS (VALUES (14,7500,3000,22,8),(21,7500,3000,22,8),(28,7500,3000,22,8)) SELECT days || ' 天' AS days, MIN(procurement_pool/(procurement_per_order*days), logistics_pool/(logistics_per_order*days)) AS capacity, procurement_per_order AS procurement, logistics_per_order AS logistics, procurement_pool+logistics_pool AS working_capital FROM scenarios ORDER BY scenarios.days
